// === Tab: mySketch ===
let x=[];
let y=[];
let o=[];
let xSpeed=[];
let ySpeed=[];
let num=100;

function setup() {
  createCanvas(windowWidth, windowHeight);
  for (let i=0;i<num;i++) {
    x[i]=random(width);
    y[i]=random(height);
    o[i]=random(5, 10);
    xSpeed[i]=random(-1, 1);
    ySpeed[i]=random(-1, 1);
  }
}
function draw(){
  background(20);
  fill(random(200,255));
  noStroke(); 

  for (let i=0;i<num;i++) {
    ellipse(x[i],y[i],o[i]);
    x[i]+=xSpeed[i];
    y[i]+=ySpeed[i];

    if (x[i] > width||x[i]<0){
      xSpeed[i] *= -1;
    }
    if (y[i] > height||y[i]<0){
      ySpeed[i] *= -1;
    }
  }
  stroke(150, 200, 255, 100);
  strokeWeight(1);

  for (let i = 0; i < num; i++) {
    for (let j = 0; j < num; j++) {
      let d = dist(x[i], y[i], x[j], y[j]);
      if (d<75) {
        line(x[i], y[i], x[j], y[j]);
      }
    }
  }
}
